package e2e

import (
	"testing"

	"github.com/stretchr/testify/assert"
	apiextensionsv1 "k8s.io/apiextensions-apiserver/pkg/apis/apiextensions/v1"

	"github.com/argoproj/argo-cd/v3/pkg/apis/application/v1alpha1"
	"github.com/argoproj/argo-cd/v3/test/e2e/fixture"
	. "github.com/argoproj/argo-cd/v3/test/e2e/fixture/applicationsets"
)

// TestSuspendOfGeneratedApplicationIsKept suspends an Application generated by an ApplicationSet with its action. The
// ApplicationSet keeps the annotation when it updates the Application, unless its template sets the annotation.
func TestSuspendOfGeneratedApplicationIsKept(t *testing.T) {
	const appName = "suspend-generated"
	appSet := v1alpha1.ApplicationSet{
		Spec: v1alpha1.ApplicationSetSpec{
			Template: v1alpha1.ApplicationSetTemplate{
				ApplicationSetTemplateMeta: v1alpha1.ApplicationSetTemplateMeta{Name: "{{name}}"},
				Spec: v1alpha1.ApplicationSpec{
					Project: "default",
					Source: &v1alpha1.ApplicationSource{
						RepoURL:        fixture.RepoURL(fixture.RepoURLTypeFile),
						TargetRevision: "HEAD",
						Path:           "suspend",
					},
					Destination: v1alpha1.ApplicationDestination{
						Server:    "https://kubernetes.default.svc",
						Namespace: fixture.TestNamespace(),
					},
				},
			},
			Generators: []v1alpha1.ApplicationSetGenerator{{
				List: &v1alpha1.ListGenerator{
					Elements: []apiextensionsv1.JSON{{Raw: []byte(`{"name": "` + appName + `"}`)}},
				},
			}},
		},
	}

	Given(t).
		When().
		Create(appSet).
		And(func() {
			waitForApplication(t, appName, func(*v1alpha1.Application) bool { return true })
			runToggleSuspend(t, fixture.TestNamespace(), appName)
			waitForApplication(t, appName, (*v1alpha1.Application).IsSuspended)
		}).
		// a template change makes the ApplicationSet controller update the Application
		Update(func(appset *v1alpha1.ApplicationSet) {
			appset.Spec.Template.Labels = map[string]string{"e2e.argoproj.io/updated": "true"}
		}).
		And(func() {
			app := waitForApplication(t, appName, func(app *v1alpha1.Application) bool {
				return app.Labels["e2e.argoproj.io/updated"] == "true"
			})
			assert.True(t, app.IsSuspended(), "the ApplicationSet removed the suspend annotation")
		}).
		Update(func(appset *v1alpha1.ApplicationSet) {
			appset.Spec.Template.Annotations = map[string]string{v1alpha1.AnnotationKeySuspend: "false"}
		}).
		And(func() {
			app := waitForApplication(t, appName, func(app *v1alpha1.Application) bool {
				return app.Annotations[v1alpha1.AnnotationKeySuspend] == "false"
			})
			assert.False(t, app.IsSuspended())
		})
}
